112	// driftThreshold: minimum distinct-value count before a state key is flagged
113	// as likely unbounded (see the drift detector inside explore()); exposed as an
114	// option for tests — the default is deliberately far below the maxStates
115	// default so a runaway machine warns long before the cap grinds.
116	export function check({ specModule, contract, invariants = {}, maxStates = 100000, initialStates = [], steps: providedSteps = null, driftThreshold = 1000 }) {
117	  // ── Admission ─────────────────────────────────────────────────────────────
118	  // TWO shapes are admitted, and neither is hand-authorable:
119	  //   1. a v2 SAM strict-profile module — driven through the {init,transition}
120	  //      adapter (rejections return the input state, a legal observable no-op)
121	  //      with the (action, data) domain read from the spec's OWN manifest();
122	  //   2. an ALREADY-ADAPTED relation {init, transition} — produced only by
123	  //      makeSamAdapter or by mutating its output (scripts/mutate.mjs, polynv's
124	  //      mutation grade), and admitted only WITH an explicit `steps` domain,
125	  //      since a bare relation carries no manifest to read one from.
126	  // A 1.x bare-next module ({init, next}) satisfies neither and is refused.
127	  let mod = specModule;
128	  let steps, notes;
129	  let internalKeys = [];
130	  let engine = 'sam-v2';
131	  const preAdapted = !!specModule
132	    && typeof specModule.transition === 'function'
133	    && typeof specModule.init === 'function'
134	    && !isSamV2Module(specModule);
135	  if (preAdapted) {
136	    if (!providedSteps) {
137	      return { ok: false, error: 'an adapted {init, transition} relation must be explored over an explicit `steps` domain (it carries no manifest())', statesExplored: 0, capHit: false, violations: [], domainNotes: [], frozenKeys: [], driftWarnings: [], engine: 'adapted' };
138	    }
139	    engine = 'adapted';
140	    steps = providedSteps;
141	    notes = [];
142	  } else if (!isSamV2Module(specModule)) {
143	    const legacy = specModule && typeof specModule.next === 'function' && typeof specModule.init === 'function';
144	    return {
145	      ok: false,
146	      error: legacy
147	        ? "spec exports a bare next(state, action, data) — the 1.x artifact contract, removed in 8.0.0. Author a SAM v2 strict-profile module (polygen writes one; see examples/turnstile-v2)."
148	        : 'spec must export the v2 SAM surface { instance, init, actions, getState, setState }',
149	      statesExplored: 0, capHit: false, violations: [], domainNotes: [], frozenKeys: [], driftWarnings: [], engine: null,
150	    };
151	  } else {
152	    try {
153	      mod = makeSamAdapter(specModule);
154	      // The library's own obligation check FIRST: a module with no named
155	      // intents / schemas / domains would otherwise explore nothing and pass
156	      // vacuously. Strict modules throw here; non-strict ones RETURN the
157	      // problems array — both must fail loudly.
158	      const accessor = specModule.instance({});
159	      if (typeof accessor.validate === 'function') {
160	        const problems = accessor.validate();
161	        if (Array.isArray(problems) && problems.length) {
162	          return { ok: false, error: `v2 module fails validate(): ${problems.join('; ')}`, statesExplored: 0, capHit: false, violations: [], domainNotes: [], frozenKeys: [], driftWarnings: [], engine: 'sam-v2' };
