172	      // frozen-key scan cannot even see it. Noted loudly, per key.
173	      const shape = specModule.instance({}).manifest()?.modelShape || null;
174	      const derivedKeys = shape ? Object.keys(shape).filter((k) => shape[k] && shape[k].derived === true) : [];
175	      if (derivedKeys.length) {
176	        return { ok: false, error: `modelShape declares reactor-owned (derived: true) key(s) ${derivedKeys.map((k) => `'${k}'`).join(', ')} — the strict profile requires reactors: [], and state computed outside the acceptor step cannot be explored faithfully`, statesExplored: 0, capHit: false, violations: [], domainNotes: [], frozenKeys: [], driftWarnings: [], engine: 'sam-v2' };
