188	      // ARE in the manifest but lack a domain already get their own note.)
189	      // intentNames comes from the SAME manifest() read the domain came from,
190	      // so note and domain cannot disagree even if the getter is impure.
191	      const manifestIntents = new Set(intentNames);
192	      for (const a of Object.keys(contract?.actions || {})) {
193	        if (!manifestIntents.has(a)) notes.push(`contract action '${a}' is not in the module's manifest() — NOT explored`);
194	      }
195	      // An explicit domain still wins for a v2 module: callers that must
196	      // explore two modules over the SAME alphabet (polynv's mutation grade)
197	      // pass the original's steps so a verdict can never be a domain artifact.
198	      if (providedSteps) { steps = providedSteps; notes = []; }
199	    } catch (e) {
200	      return { ok: false, error: `v2 SAM module rejected by the adapter: ${e && e.message}`, statesExplored: 0, capHit: false, violations: [], domainNotes: [], frozenKeys: [], driftWarnings: [], engine: 'sam-v2' };
201	    }
202	  }
203	  // An empty exploration domain would visit only init() and pass every
204	  // invariant vacuously — that is a failed check, never a clean one.
205	  if (!steps.length) {
206	    const why = engine === 'sam-v2'
207	      ? "the module's manifest() yields no explorable (action, data) steps"
208	      : 'the caller supplied an empty `steps` domain';
209	    return { ok: false, error: `exploration domain is empty — ${why}${notes.length ? ` [${notes.join('; ')}]` : ''}`, statesExplored: 0, capHit: false, violations: [], domainNotes: notes, frozenKeys: [], driftWarnings: [], engine };
210	  }
211	  const stateInv = invariants.stateInvariants || [];
212	  const transInv = invariants.transitionInvariants || [];
213	  // Rejection invariants: pred(state, action, data, verdict) with verdict
214	  // { rejected: bool, reason: string|null } — TRUE when the rule HOLDS. This
215	  // is the invariant class bare-next could never express: an obligation ABOUT
216	  // the rejection itself ("PUSH while LOCKED must be REJECTED, with reason
217	  // X"), not merely about the post-state (post == pre is a weaker claim a
218	  // silently no-oping acceptor also satisfies).
219	  const rejInv = invariants.rejectionInvariants || [];
220	  const hasStep = typeof mod.step === 'function';
221	  if (rejInv.length && !hasStep) {
222	    // A pre-adapted bare relation carries no verdicts — evaluating rejection
223	    // obligations over it would pass vacuously. Refuse, never silently skip.
224	    return { ok: false, error: 'rejectionInvariants need step() verdicts (a v2 SAM module through the adapter) — the supplied {init, transition} relation carries none', statesExplored: 0, capHit: false, violations: [], domainNotes: notes, frozenKeys: [], driftWarnings: [], engine };
225	  }
