227	  // One full BFS exploration. Kept as an inner function so the determinism
228	  // double-pass below can run it twice under identical inputs. `live` labels
229	  // the pass for the progress heartbeat; live console output NEVER enters the
230	  // determinism digest (heartbeats are clock-driven; drift warnings are
231	  // deterministic but printed only on pass 1 to avoid duplicates).
232	  const explore = (live = null) => {
233	    const violations = [];
234	    const rejectionsSeen = new Map(); // reason -> count of explored rejected steps
235	    // ── Runaway guardrails (eval/FINDING-raft-field-study.md, lesson 2) ─────
236	    // An action that mints a fresh state forever (an unbounded monotonic
237	    // counter: raft's ElectionTimeout term bump) turns the default cap into a
238	    // silent multi-minute grind. The fix is telling the user EARLY, not
239	    // guessing a universal bound: (a) a drift detector — a key whose distinct
240	    // values track the number of discovered states is likely unbounded; (b) a
241	    // heartbeat line every ~10s so a long run is visibly alive and visibly
242	    // runaway. Both stderr-only; drift is also recorded in the result.
243	    const keyValues = new Map(); // key -> Set(stable(value)) over all graph states
244	    const driftWarned = new Set();
245	    const driftWarnings = [];
246	    const trackDrift = (state) => {
247	      if (!state || typeof state !== 'object' || Array.isArray(state)) return;
248	      for (const [k, v] of Object.entries(state)) {
249	        (keyValues.get(k) || keyValues.set(k, new Set()).get(k)).add(stable(v));
250	      }
251	    };
252	    // KNOWN SCOPE LIMIT: the detector is single-key (the raft term-bump
253	    // shape). A blowup that is a PRODUCT of two or more moderately-sized keys
