255	    // ratio near zero and is invisible here — the heartbeat is the only
256	    // signal for that shape. Absence of a drift warning is NOT evidence of
257	    // boundedness.
258	    const checkDrift = (discovered) => {
259	      for (const [k, vals] of keyValues) {
260	        if (driftWarned.has(k) || vals.size < driftThreshold || vals.size < discovered * 0.5) continue;
261	        driftWarned.add(k);
262	        const msg = `state key '${k}' has ${vals.size} distinct values across ${discovered} discovered states and is still growing — the state space is likely unbounded in this key; abstract it in the contract or use a much smaller --max-states`;
263	        driftWarnings.push(msg);
264	        if (live === 'pass 1') stderrLine(`[check] WARNING: ${msg}`);
265	      }
266	    };
267	    // Env override validated: NaN (typo) falls back to the default instead of
268	    // silently disabling the heartbeat; negative values clamp to 0.
269	    const hbRaw = Number(process.env.POLYGRAPH_HEARTBEAT_MS ?? 10000);
270	    const heartbeatMs = Number.isFinite(hbRaw) ? Math.max(0, hbRaw) : 10000;
271	    const started = Date.now();
272	    let lastBeat = started;
273	    const seen = new Set(); // invariant names already recorded (keep shortest = first via BFS)
274	    let capHit = false;
275	    let init;
276	    try { init = mod.init(); }
277	    catch (e) { return { error: `init() threw: ${e && e.message}`, parent: new Map(), violations, capHit, seededStates: 0, driftWarnings }; }
