352	            post = r.state;
353	            verdict = { rejected: r.verdict === 'rejected', reason: r.reason ?? null };
354	          } else {
355	            post = mod.transition(JSON.parse(sJson), action, data);
356	            verdict = null; // bare relation: no rejection semantics available
