410	    return { parent, violations, capHit, seededStates, driftWarnings, rejectionsSeen };
411	  };
412	
413	  // ── Determinism double-pass ───────────────────────────────────────────────
414	  // Two identical explorations must produce the SAME state graph and the SAME
415	  // violations. A digest mismatch means the spec's transitions depend on
416	  // something outside (state, action, data) — Math.random, Date.now, retained
417	  // mutable module state — which invalidates both replay and exploration, so
418	  // it is surfaced as a first-class 'nondeterministic' finding.
419	  const digestOf = (r) => stable({
420	    states: [...r.parent.keys()].sort(),
421	    violations: r.violations.map((v) => ({ invariant: v.invariant, kind: v.kind, detail: v.detail })),
