488	  // nothing about absence).
489	  let rejectionReport = null;
490	  if (hasStep) {
491	    const declared = (contract?.specialRules || []).map((r) => r && r.name).filter(Boolean);
492	    const fired = Object.fromEntries([...rejectionsSeen.entries()].sort());
493	    rejectionReport = {
494	      fired,
495	      declared,
496	      missing: declared.filter((name) => !rejectionsSeen.has(name)),
497	      bounded: capHit,
498	    };
499	  }
500	  return { ok: violations.length === 0, statesExplored: parent.size - seededStates, seededStates, capHit, violations, domainNotes: notes, frozenKeys, driftWarnings, engine, nondeterministic, rejectionReport, internalKeys };
501	}
502	
503	// ── Readable render ─────────────────────────────────────────────────────────
504	export function render(result) {
505	  const L = [];
506	  L.push(`states explored: ${result.statesExplored}${result.seededStates ? ` (+ ${result.seededStates} seeded)` : ''}${result.capHit ? ' (CAP HIT — exploration bounded)' : ''}`);
507	  if (result.error) { L.push(`ERROR: ${result.error}`); return L.join('\n'); }
508	  // Silent alphabet pruning must be VISIBLE: an action skipped for lack of a
509	  // data domain means the clean verdict below only covers the explored subset.
510	  const notes = result.domainNotes || [];
511	  for (const n of notes) L.push(`WARNING: ${n}`);
512	  // A likely-unbounded key means the cap (not the machine) decided where
513	  // exploration stopped — the verdict below covers an arbitrary prefix.
514	  for (const d of result.driftWarnings || []) L.push(`WARNING: ${d}`);
515	  // A frozen key means part of the machine's behavior space was structurally
516	  // out of reach — the clean verdict below is silent about anything it gates.
517	  for (const f of result.frozenKeys || []) {
518	    L.push(`WARNING: state key '${f.key}' is frozen at ${JSON.stringify(f.value)} — no explored action or seed ever changes it; if it gates behavior, this check cannot verify that behavior (seed --initial-states or capture traces with a non-default value)`);
519	  }
520	  // Internal keys: the modelShape sibling of the frozen-key warning — pinned
521	  // at init values by the adapter's purity discipline, invisible to the
522	  // frozen scan itself.
523	  for (const k of result.internalKeys || []) {
524	    L.push(`WARNING: internal modelShape key '${k}' is pinned at its init value during exploration — behavior gated on a non-default value of it is NOT explored (and is invisible to the frozen-key scan)`);
525	  }
526	  // Rejection coverage: the exhaustive-tier cross-check of the contract's
527	  // specialRules — each declared rejection must actually FIRE somewhere in
528	  // the explored graph, with its declared reason.
529	  const rr = result.rejectionReport;
530	  if (rr) {
531	    const firedNames = Object.keys(rr.fired);
532	    if (firedNames.length) L.push(`rejections explored: ${firedNames.map((n) => `${n} ×${rr.fired[n]}`).join(', ')}`);
533	    for (const name of rr.missing) {
534	      L.push(`WARNING: declared special rule '${name}' NEVER fired as a rejection over the explored graph${rr.bounded ? ' (exploration was bounded — raise --max-states before reading this as absence)' : ''} — the rule is unreachable over the declared domain, or the code rejects with a different reason`);
535	    }
536	  }
537	  if (result.ok) {
538	    L.push(notes.length
539	      ? `no invariant violations reachable over the EXPLORED alphabet ✓ (${notes.length} action/field(s) skipped — see warnings above)`
540	      : 'no invariant violations reachable ✓');
541	    return L.join('\n');
542	  }
543	  L.push(`${result.violations.length} invariant violation(s):`);
544	  for (const v of result.violations) {
545	    L.push(`\n  ✗ ${v.invariant} [${v.kind}] — ${v.detail}`);
546	    if (!v.path.length) continue; // e.g. a nondeterminism finding has no single counterexample path
547	    const fromSeed = v.path[0] && v.path[0].origin === 'seed';
548	    L.push(`    counterexample (shortest path from ${fromSeed ? 'a seeded state' : 'init'}):`);
549	    v.path.forEach((step, i) => {
550	      const st = typeof step.state === 'string' ? step.state : JSON.stringify(step.state);
551	      if (i === 0 && step.action === null) L.push(`      ${fromSeed ? 'seed' : 'init'}            ${st}`);
552	      else L.push(`      ${step.action}(${JSON.stringify(step.data)}) -> ${st}${step.rejected ? ` [REJECTED: ${JSON.stringify(step.reason)}]` : ''}`);
553	    });
554	  }
555	  return L.join('\n');
556	}
557	
558	// ── CLI ─────────────────────────────────────────────────────────────────────
559	async function loadInvariants(path) {
560	  if (!path) return {};
561	  const mod = await import(pathToFileURL(resolve(path)).href);
562	  return mod.default || mod;
563	}
564	
565	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
566	  const args = {};
567	  for (let i = 2; i < process.argv.length; i++) if (process.argv[i].startsWith('--')) { args[process.argv[i].slice(2)] = process.argv[i + 1]; i++; }
568	  if (!args.spec || !args.contract) { console.error('usage: node check.mjs --spec <mod.js> --contract <c.json> [--invariants <inv.mjs>] [--initial-states <states.json>] [--max-states N] [--json out]'); process.exit(2); }
569	  const contract = JSON.parse(readFileSync(args.contract, 'utf-8'));
570	  const invariants = await loadInvariants(args.invariants);
571	  const specModule = loadSpec(args.spec);
572	  // --initial-states: a .json array of state objects seeded into the BFS
573	  // alongside init() — the versioning check "can any of THESE states be
574	  // driven to a violation under these rules". Malformed input is a usage
575	  // error (exit 2), never a stack trace and never 'machine bug' findings.
576	  let initialStates = [];
577	  if (args['initial-states']) {
578	    try {
579	      initialStates = JSON.parse(readFileSync(args['initial-states'], 'utf-8'));
580	    } catch (e) {
581	      console.error(`--initial-states '${args['initial-states']}': ${e && e.message}`); process.exit(2);
582	    }
583	    if (!Array.isArray(initialStates)) { console.error(`--initial-states '${args['initial-states']}' must be a JSON array of states`); process.exit(2); }
584	    const bad = initialStates.findIndex((s) => !s || typeof s !== 'object' || Array.isArray(s));
585	    if (bad >= 0) { console.error(`--initial-states '${args['initial-states']}': element ${bad} is not a state object — seeding non-states would report input garbage as machine findings`); process.exit(2); }
586	  }
587	  const result = check({ specModule, contract, invariants, maxStates: Number(args['max-states'] || 100000), initialStates });
588	  console.log(render(result));
589	  if (args.json) { const { writeFileSync } = await import('node:fs'); writeFileSync(args.json, JSON.stringify(result, null, 2)); }
590	  process.exit(result.ok ? 0 : 1);
591	}
