{
  "name": "checkout-two-carts",
  "source": "src/core.ts",
  "stateKeys": ["aStatus", "aItems", "bStatus", "bItems", "available", "reserved", "charged", "declining", "net"],
  "initState": {
    "aStatus": "none", "aItems": 0,
    "bStatus": "none", "bItems": 0,
    "available": 2, "reserved": 0,
    "charged": 0, "declining": false,
    "net": []
  },
  "terminalStates": [],
  "noOpRule": "A command the code refuses, and a DELIVER of a message not in transit, yield post == pre.",
  "actions": {
    "OPEN": { "dataFields": { "cart": "string" } },
    "ADD": { "dataFields": { "cart": "string" } },
