// Captures NDJSON traces from src/core.ts for replay against spec/model/checkout.js.
// Run: node spec/capture.ts   (writes spec/traces/*.ndjson)

import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { Core } from '../src/core.ts';
import type { Action, State } from '../src/core.ts';
import type { Message } from '../src/types.ts';

const CARTS = ['a', 'b'];

const msgName = (m: Message): string => {
  const n = m.action === 'Reserve' || m.action === 'Release' ? `:${m.data.qty}` : m.action === 'Charge' ? `:${m.data.amount}` : '';
  return `${m.from}>${m.to}:${m.action}${n}`;
};

function project(s: State) {
  const out: Record<string, unknown> = {};
  for (const c of CARTS) {
    out[`${c}Status`] = s.carts[c] ? s.carts[c].status : 'none';
    out[`${c}Items`] = s.carts[c] ? s.carts[c].items : 0;
  }
  return { ...out, available: s.available, reserved: s.reserved, charged: s.charged, declining: s.declining, net: s.inFlight.map(msgName).sort() };
}

const NAMES: Record<string, string> = {
  open: 'OPEN', add: 'ADD', checkout: 'CHECKOUT', cancel: 'CANCEL',
  declineCards: 'DECLINE_CARDS', acceptCards: 'ACCEPT_CARDS', deliver: 'DELIVER',
};

class Recorder {
  core = new Core();
  lines: string[] = [];
  do(action: Action, data: Record<string, unknown> = {}) {
    const pre = project(this.core.state);
    let specData = data;
    if (action === 'deliver') {
      const m = this.core.state.inFlight.find((x) => x.id === data.id)!;
      specData = { msg: msgName(m) };
    }
    this.core.step(action, data);
    this.lines.push(JSON.stringify({ pre, action: NAMES[action], data: specData, post: project(this.core.state) }));
  }
  deliverFirst(pred: (m: Message) => boolean = () => true) {
    const m = this.core.state.inFlight.find(pred);
    if (m) this.do('deliver', { id: m.id });
  }
  deliverAll() { while (this.core.state.inFlight.length) this.deliverFirst(); }
}

const scenarios: Record<string, (r: Recorder) => void> = {
  happy(r) { r.do('open', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('checkout', { cart: 'a' }); r.do('cancel', { cart: 'a' }); r.deliverAll(); r.do('cancel', { cart: 'a' }); r.do('add', { cart: 'a' }); },
  declined(r) { r.do('acceptCards'); r.do('declineCards'); r.do('declineCards'); r.do('open', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('checkout', { cart: 'a' }); r.deliverFirst(); r.deliverFirst(); r.do('cancel', { cart: 'a' }); r.deliverAll(); r.do('acceptCards'); },
  outOfStock(r) { r.do('open', { cart: 'a' }); r.do('open', { cart: 'a' }); r.do('open', { cart: 'b' }); r.do('add', { cart: 'a' }); r.do('add', { cart: 'b' }); r.do('add', { cart: 'b' }); r.do('checkout', { cart: 'b' }); r.do('checkout', { cart: 'a' }); r.deliverFirst((m) => m.from === 'b'); r.deliverFirst(); r.deliverAll(); },
  cancelling(r) { r.do('checkout', { cart: 'a' }); r.do('cancel', { cart: 'b' }); r.do('add', { cart: 'b' }); r.do('open', { cart: 'a' }); r.do('checkout', { cart: 'a' }); r.do('cancel', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('checkout', { cart: 'a' }); r.do('cancel', { cart: 'a' }); r.do('cancel', { cart: 'a' }); r.deliverAll(); r.do('open', { cart: 'b' }); r.do('cancel', { cart: 'b' }); },
  cancelOutOfStock(r) { r.do('open', { cart: 'a' }); r.do('open', { cart: 'b' }); r.do('add', { cart: 'a' }); r.do('add', { cart: 'a' }); r.do('add', { cart: 'b' }); r.do('checkout', { cart: 'a' }); r.do('checkout', { cart: 'b' }); r.deliverFirst((m) => m.from === 'a'); r.do('cancel', { cart: 'b' }); r.deliverAll(); },
};

// Seeded random walks over the same alphabet.
function walk(seed: number) {
  return (r: Recorder) => {
    let x = seed;
    const rand = (n: number) => { x = (x * 1103515245 + 12345) % 2147483648; return x % n; };
    for (let i = 0; i < 40; i++) {
      const k = rand(8);
      const cart = CARTS[rand(2)];
      if (k === 0) r.do('open', { cart });
      else if (k === 1) r.do('add', { cart });
      else if (k === 2) r.do('checkout', { cart });
      else if (k === 3) r.do('cancel', { cart });
      else if (k === 4) r.do(rand(2) ? 'declineCards' : 'acceptCards');
      else if (r.core.state.inFlight.length) {
        const m = r.core.state.inFlight[rand(r.core.state.inFlight.length)];
        r.do('deliver', { id: m.id });
      }
    }
  };
}
for (let s = 1; s <= 12; s++) scenarios[`walk${s}`] = walk(s * 7919);

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, run] of Object.entries(scenarios)) {
  const r = new Recorder();
  run(r);
  writeFileSync(new URL(`${name}.ndjson`, dir), r.lines.join('\n') + '\n');
}
console.log(`captured ${Object.keys(scenarios).length} traces`);

