  bStatus: 'none', bItems: 0,
  available: 2, reserved: 0,
  charged: 0, declining: false,
  net: [],
};

const ALL_KEYS = Object.keys(INITIAL_STATE);

const MESSAGES = [];
for (const c of CARTS) {
  for (let n = 1; n <= MAX_ITEMS; n++) {
    MESSAGES.push(`${c}>inventory:Reserve:${n}`, `${c}>payments:Charge:${n}`, `${c}>inventory:Release:${n}`);
