'use strict';

// SAM v2 strict-profile specification of src/core.ts, over three carts "a", "b"
// and "c" (three, so that returns can push charges against the limit of 4).
// A cart that was never opened has status 'none'. The network is `net`: the
// sorted list of messages in transit, each written "from>to:Action[:n]" where
// n is the Reserve/Release qty or the Charge/Refund amount.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CARTS = ['a', 'b', 'c'];
const MAX_ITEMS = 2;
const CHARGE_LIMIT = 4;

const INITIAL_STATE = {};
const CART_SHAPE = {};
for (const c of CARTS) {
  INITIAL_STATE[`${c}Status`] = 'none';
  INITIAL_STATE[`${c}Items`] = 0;
  CART_SHAPE[`${c}Status`] = { type: 'string' };
  CART_SHAPE[`${c}Items`] = { type: 'number' };
}
Object.assign(INITIAL_STATE, { available: 2, reserved: 0, charged: 0, declining: false, net: [] });

const ALL_KEYS = Object.keys(INITIAL_STATE);

const MESSAGES = [];
for (const c of CARTS) {
  for (let n = 1; n <= MAX_ITEMS; n++) {
    MESSAGES.push(`${c}>inventory:Reserve:${n}`, `${c}>payments:Charge:${n}`, `${c}>inventory:Release:${n}`, `${c}>payments:Refund:${n}`);
  }
  MESSAGES.push(`inventory>${c}:Reserved`, `inventory>${c}:OutOfStock`, `payments>${c}:Charged`, `payments>${c}:Declined`);
}

const cartDomain = CARTS.map((cart) => ({ cart }));
const cartSchema = { cart: { type: 'string' } };
const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const sorted = (list) => [...list].sort();

// Frame every key not in `written`.
const frame = (unchanged, written) => unchanged(...ALL_KEYS.filter((k) => !written.includes(k)));

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      ...CART_SHAPE,
      available: { type: 'number' }, reserved: { type: 'number' },
      charged: { type: 'number' }, declining: { type: 'boolean' },
      net: { type: 'array' },
    },
    actions: {
      OPEN: intent(cartSchema, cartDomain),
      ADD: intent(cartSchema, cartDomain),
      CHECKOUT: intent(cartSchema, cartDomain),
      CANCEL: intent(cartSchema, cartDomain),
      RETURN: intent(cartSchema, cartDomain),
      DECLINE_CARDS: intent({}, [{}]),
      ACCEPT_CARDS: intent({}, [{}]),
      DELIVER: intent({ msg: { type: 'string' } }, MESSAGES.map((msg) => ({ msg }))),
    },
    acceptors: {
      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = `${cart}Status`;
        if (model[s] !== 'none') return reject('cart-exists');
        next[s] = 'open';
        frame(unchanged, [s]);
      },
      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = `${cart}Status`, i = `${cart}Items`;
        if (model[s] === 'none') return reject('no-such-cart');
        if (model[s] !== 'open') return reject('cart-not-open');
        if (model[i] >= MAX_ITEMS) return reject('cart-full');
        next[i] = model[i] + 1;
        frame(unchanged, [i]);
      },
      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = `${cart}Status`, i = `${cart}Items`;
        if (model[s] === 'none') return reject('no-such-cart');
        if (model[s] !== 'open') return reject('cart-not-open');
        if (model[i] < 1) return reject('cart-empty');
        next[s] = 'reserving';
        next.net = sorted([...model.net, `${cart}>inventory:Reserve:${model[i]}`]);
        frame(unchanged, [s, 'net']);
      },
      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = `${cart}Status`;
        if (model[s] === 'none') return reject('no-such-cart');
        if (model[s] === 'open') next[s] = 'cancelled';
        else if (model[s] === 'reserving') next[s] = 'cancelling';
        else if (model[s] === 'paying') return reject('payment-in-progress');
        else return reject('cart-closed');
        frame(unchanged, [s]);
      },
      RETURN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = `${cart}Status`, i = `${cart}Items`;
        if (model[s] === 'none') return reject('no-such-cart');
        if (model[s] !== 'paid') return reject('cart-not-paid');
        next[s] = 'returned';
        next.net = sorted([...model.net, `${cart}>payments:Refund:${model[i]}`, `${cart}>inventory:Release:${model[i]}`]);
        frame(unchanged, [s, 'net']);
      },
      DECLINE_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        next.declining = true;
        frame(unchanged, ['declining']);
      },
      ACCEPT_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        next.declining = false;
        frame(unchanged, ['declining']);
      },
      DELIVER: (model) => ({ msg }, { reject, next, unchanged }) => {
        const at = model.net.indexOf(msg);
        if (at < 0) return reject('not-in-flight');
        const rest = model.net.filter((_, k) => k !== at);
        const [route, action, nText] = msg.split(':');
        const [from, to] = route.split('>');
        const n = Number(nText);
        const written = ['net'];
        const send = [];
        if (to === 'inventory' && action === 'Reserve') {
          if (n <= model.available) {
            next.available = model.available - n;
            next.reserved = model.reserved + n;
            written.push('available', 'reserved');
            send.push(`inventory>${from}:Reserved`);
          } else {
            send.push(`inventory>${from}:OutOfStock`);
          }
        } else if (to === 'inventory' && action === 'Release') {
          next.available = model.available + n;
          next.reserved = model.reserved - n;
          written.push('available', 'reserved');
        } else if (to === 'payments' && action === 'Charge') {
          if (model.declining || model.charged + n > CHARGE_LIMIT) {
            send.push(`payments>${from}:Declined`);
          } else {
            next.charged = model.charged + n;
            written.push('charged');
            send.push(`payments>${from}:Charged`);
          }
        } else if (to === 'payments' && action === 'Refund') {
          next.charged = model.charged - n;
          written.push('charged');
        } else {
          // to a cart
          const s = `${to}Status`, items = model[`${to}Items`];
          const st = model[s];
          let status = st;
          if (action === 'Reserved') {
            if (st === 'reserving') { status = 'paying'; send.push(`${to}>payments:Charge:${items}`); }
            else if (st === 'cancelling') { status = 'cancelled'; send.push(`${to}>inventory:Release:${items}`); }
          } else if (action === 'OutOfStock') {
            if (st === 'reserving') status = 'failed';
            else if (st === 'cancelling') status = 'cancelled';
          } else if (action === 'Charged') {
            if (st === 'paying') status = 'paid';
          } else if (action === 'Declined') {
            if (st === 'paying') { status = 'failed'; send.push(`${to}>inventory:Release:${items}`); }
          }
          if (status !== st) { next[s] = status; written.push(s); }
        }
        next.net = sorted([...rest, ...send]);
        frame(unchanged, written);
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  OPEN: (data = {}) => intents.OPEN(data),
  ADD: (data = {}) => intents.ADD(data),
  CHECKOUT: (data = {}) => intents.CHECKOUT(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RETURN: (data = {}) => intents.RETURN(data),
  DECLINE_CARDS: (data = {}) => intents.DECLINE_CARDS(data),
  ACCEPT_CARDS: (data = {}) => intents.ACCEPT_CARDS(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

'use strict';

// SAM v2 strict-profile specification of src/core.ts, over three carts "a", "b"
// and "c" (three, so that returns can push charges against the limit of 4).
// A cart that was never opened has status 'none'. The network is `net`: the
