    pred: (pre, action, data, verdict) => !(['ADD', 'CHECKOUT', 'CANCEL', 'RETURN'].includes(action) && status(pre, data.cart) === 'none') || verdict.rejected,
  },
];

export default { stateInvariants, transitionInvariants, rejectionInvariants };

