import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.inFlight(), []);
  assert.equal(await h.cart('a'), null);
});

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false); // empty
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const [reserved] = await h.inFlight();
  assert.deepEqual([reserved.from, reserved.to, reserved.action, reserved.data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliver(reserved.id);
  assert.deepEqual(await h.cart('a'), { status: 'paying', items: 2 });
  const [charge] = await h.inFlight();
  assert.equal(charge.action, 'Charge');
  assert.deepEqual(charge.data, { from: 'a', amount: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('declined charge keeps units; abandon releases them', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a');
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  assert.equal((await h.retry('a')).ok, false);
  assert.equal((await h.abandon('a')).ok, false);
  await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'declined', items: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[c]('a')).ok, false);
  assert.equal((await h.open('a')).ok, false);
  assert.deepEqual(await h.abandon('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.equal((await h.retry('a')).ok, false);
  assert.equal((await h.abandon('a')).ok, false);
  const msgs = (await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]);
  assert.deepEqual(msgs, [['a', 'inventory', 'Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('retry a declined card', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  await h.declineCards();
  await h.checkout('a'); await h.deliverAll();
  assert.deepEqual(await h.retry('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'paying', items: 2 });
  const msgs = (await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]);
  assert.deepEqual(msgs, [['a', 'payments', 'Charge', { from: 'a', amount: 2 }]]);
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'declined');
  await h.acceptCards();
  await h.retry('a'); await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('out of stock', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  await h.open('b'); await h.add('b');
  await h.checkout('a'); await h.deliverAll();
  await h.checkout('b'); await h.deliverAll();
  assert.equal((await h.cart('b'))!.status, 'failed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
});

test('cancel while reserving gives back units', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a');
  await h.checkout('a');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('return a paid cart', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false); // open
  assert.equal((await h.returnCart('x')).ok, false);
  await h.checkout('a');
  assert.equal((await h.returnCart('a')).ok, false); // reserving
  await h.deliverAll();
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  const msgs = (await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]);
  assert.deepEqual(msgs.sort(), [['a', 'inventory', 'Release', { qty: 2 }], ['a', 'payments', 'Refund', { amount: 2 }]]);
  for (const c of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[c]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.inFlight(), []);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('charge limit after returns', async () => {
  const h = await createHost();
  for (const c of ['a', 'b', 'c']) { await h.open(c); await h.add(c); await h.add(c); }
  await h.checkout('a'); await h.deliverAll();
  await h.returnCart('a');
  const release = (await h.inFlight()).find((m) => m.action === 'Release')!;
  await h.deliver(release.id); // the refund stays in transit
  await h.checkout('b'); await h.deliver((await h.inFlight()).find((m) => m.action === 'Reserve')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Reserved')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Charge')!.id);
  assert.deepEqual(await h.payments(), { charged: 4, declining: false });
  await h.deliverAll();
  assert.equal((await h.cart('b'))!.status, 'paid');
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('cancel open; commands on unknown carts refused', async () => {
  const h = await createHost();
  for (const c of ['add', 'checkout', 'cancel'] as const) assert.equal((await h[c]('x')).ok, false);
  assert.equal((await h.open('inventory')).ok, false);
  assert.equal(await h.cart('constructor'), null);
  await h.open('a');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.add('a')).ok, false);
});

