9	const { createInstance } = require('@cognitive-fab/sam-pattern');
10	
11	const instance = createInstance({ strict: true, hasAsyncActions: false });
12	
13	const CARTS = ['a', 'b', 'c'];
14	const MAX_ITEMS = 2;
15	const CHARGE_LIMIT = 4;
16	
17	const INITIAL_STATE = {};
18	const CART_SHAPE = {};
19	for (const c of CARTS) {
20	  INITIAL_STATE[`${c}Status`] = 'none';
21	  INITIAL_STATE[`${c}Items`] = 0;
