23	  CART_SHAPE[`${c}Items`] = { type: 'number' };
24	}
25	Object.assign(INITIAL_STATE, { available: 2, reserved: 0, charged: 0, declining: false, net: [] });
26	
27	const ALL_KEYS = Object.keys(INITIAL_STATE);
28	
29	const MESSAGES = [];
30	for (const c of CARTS) {
31	  for (let n = 1; n <= MAX_ITEMS; n++) {
32	    MESSAGES.push(`${c}>inventory:Reserve:${n}`, `${c}>payments:Charge:${n}`, `${c}>inventory:Release:${n}`, `${c}>payments:Refund:${n}`);
33	  }
34	  MESSAGES.push(`inventory>${c}:Reserved`, `inventory>${c}:OutOfStock`, `payments>${c}:Charged`, `payments>${c}:Declined`);
35	}
36	
37	const cartDomain = CARTS.map((cart) => ({ cart }));
38	const cartSchema = { cart: { type: 'string' } };
39	const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });
40	
41	const sorted = (list) => [...list].sort();
42	
43	// Frame every key not in `written`.
44	const frame = (unchanged, written) => unchanged(...ALL_KEYS.filter((k) => !written.includes(k)));
45	
46	const control = instance({
47	  initialState: { ...INITIAL_STATE },
48	  component: {
49	    modelShape: {
50	      ...CART_SHAPE,
51	      available: { type: 'number' }, reserved: { type: 'number' },
52	      charged: { type: 'number' }, declining: { type: 'boolean' },
53	      net: { type: 'array' },
54	    },
55	    actions: {
56	      OPEN: intent(cartSchema, cartDomain),
57	      ADD: intent(cartSchema, cartDomain),
58	      CHECKOUT: intent(cartSchema, cartDomain),
59	      CANCEL: intent(cartSchema, cartDomain),
60	      RETURN: intent(cartSchema, cartDomain),
61	      RETRY: intent(cartSchema, cartDomain),
62	      ABANDON: intent(cartSchema, cartDomain),
63	      DECLINE_CARDS: intent({}, [{}]),
64	      ACCEPT_CARDS: intent({}, [{}]),
65	      DELIVER: intent({ msg: { type: 'string' } }, MESSAGES.map((msg) => ({ msg }))),
66	    },
67	    acceptors: {
68	      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
69	        const s = `${cart}Status`;
70	        if (model[s] !== 'none') return reject('cart-exists');
71	        next[s] = 'open';
72	        frame(unchanged, [s]);
73	      },
74	      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
75	        const s = `${cart}Status`, i = `${cart}Items`;
76	        if (model[s] === 'none') return reject('no-such-cart');
77	        if (model[s] !== 'open') return reject('cart-not-open');
78	        if (model[i] >= MAX_ITEMS) return reject('cart-full');
79	        next[i] = model[i] + 1;
80	        frame(unchanged, [i]);
81	      },
82	      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
83	        const s = `${cart}Status`, i = `${cart}Items`;
84	        if (model[s] === 'none') return reject('no-such-cart');
85	        if (model[s] !== 'open') return reject('cart-not-open');
86	        if (model[i] < 1) return reject('cart-empty');
87	        next[s] = 'reserving';
88	        next.net = sorted([...model.net, `${cart}>inventory:Reserve:${model[i]}`]);
89	        frame(unchanged, [s, 'net']);
90	      },
91	      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
92	        const s = `${cart}Status`;
93	        if (model[s] === 'none') return reject('no-such-cart');
94	        if (model[s] === 'open') next[s] = 'cancelled';
95	        else if (model[s] === 'reserving') next[s] = 'cancelling';
96	        else if (model[s] === 'paying') return reject('payment-in-progress');
97	        else return reject('cart-closed');
98	        frame(unchanged, [s]);
99	      },
100	      RETURN: (model) => ({ cart }, { reject, next, unchanged }) => {
101	        const s = `${cart}Status`, i = `${cart}Items`;
102	        if (model[s] === 'none') return reject('no-such-cart');
103	        if (model[s] !== 'paid') return reject('cart-not-paid');
104	        next[s] = 'returned';
105	        next.net = sorted([...model.net, `${cart}>payments:Refund:${model[i]}`, `${cart}>inventory:Release:${model[i]}`]);
106	        frame(unchanged, [s, 'net']);
107	      },
108	      RETRY: (model) => ({ cart }, { reject, next, unchanged }) => {
109	        const s = `${cart}Status`, i = `${cart}Items`;
110	        if (model[s] === 'none') return reject('no-such-cart');
111	        if (model[s] !== 'declined') return reject('cart-not-declined');
112	        next[s] = 'paying';
113	        next.net = sorted([...model.net, `${cart}>payments:Charge:${model[i]}`]);
114	        frame(unchanged, [s, 'net']);
115	      },
116	      ABANDON: (model) => ({ cart }, { reject, next, unchanged }) => {
117	        const s = `${cart}Status`, i = `${cart}Items`;
118	        if (model[s] === 'none') return reject('no-such-cart');
119	        if (model[s] !== 'declined') return reject('cart-not-declined');
120	        next[s] = 'failed';
121	        next.net = sorted([...model.net, `${cart}>inventory:Release:${model[i]}`]);
122	        frame(unchanged, [s, 'net']);
123	      },
124	      DECLINE_CARDS: (model) => (_p, { reject, next, unchanged }) => {
125	        if (model.declining) return reject('already-declining');
126	        next.declining = true;
127	        frame(unchanged, ['declining']);
128	      },
129	      ACCEPT_CARDS: (model) => (_p, { reject, next, unchanged }) => {
130	        if (!model.declining) return reject('already-accepting');
131	        next.declining = false;
132	        frame(unchanged, ['declining']);
133	      },
134	      DELIVER: (model) => ({ msg }, { reject, next, unchanged }) => {
135	        const at = model.net.indexOf(msg);
136	        if (at < 0) return reject('not-in-flight');
137	        const rest = model.net.filter((_, k) => k !== at);
138	        const [route, action, nText] = msg.split(':');
139	        const [from, to] = route.split('>');
140	        const n = Number(nText);
141	        const written = ['net'];
