151	          }
152	        } else if (to === 'inventory' && action === 'Release') {
153	          next.available = model.available + n;
154	          next.reserved = model.reserved - n;
155	          written.push('available', 'reserved');
156	        } else if (to === 'payments' && action === 'Charge') {
