// The rules the brief requires, over the spec in spec/model/checkout.js.

// Same cart set as the spec (CHECKOUT_CARTS, default three carts).
const CARTS = (process.env.CHECKOUT_CARTS || 'abc').split('');
const TOTAL = 2;
const LIMIT = 4;
const status = (s, c) => s[`${c}Status`];
const items = (s, c) => s[`${c}Items`];
const unitsIn = (s, st) => CARTS.reduce((n, c) => n + (status(s, c) === st ? items(s, c) : 0), 0);
const paidUnits = (s) => unitsIn(s, 'paid');
const has = (s, msg) => s.net.includes(msg);
const inFlightSum = (s, kind) => s.net.filter((m) => m.includes(`:${kind}:`)).reduce((n, m) => n + Number(m.split(':')[2]), 0);
// Units the inventory holds for cart c right now, read off its status and the network.
const heldFor = (s, c) => {
  const st = status(s, c);
  if (st === 'paid' || st === 'paying' || st === 'declined') return items(s, c);
  if ((st === 'reserving' || st === 'cancelling') && has(s, `inventory>${c}:Reserved`)) return items(s, c);
  return 0;
};
// Amount the payment service holds for cart c right now.
const chargedFor = (s, c) => {
  const st = status(s, c);
  if (st === 'paid' || (['paying', 'abandoning'].includes(st) && has(s, `payments>${c}:Charged`))) return items(s, c);
  // A returned cart, or an abandoned one whose charge went through, has a Refund in transit.
  if (has(s, `${c}>payments:Refund:${items(s, c)}`)) return items(s, c);
  return 0;
};
const delivered = (action, data, msg) => action === 'DELIVER' && data.msg === msg;
const TERMINAL = ['failed', 'cancelled', 'returned'];

export const stateInvariants = [
  { name: 'stock-conserved', pred: (s) => s.available >= 0 && s.reserved >= 0 && s.available + s.reserved === TOTAL },
  // A Release in transit is still reserved until the inventory receives it.
  { name: 'reserved-is-held-units', pred: (s) => s.reserved === CARTS.reduce((n, c) => n + heldFor(s, c), 0) + inFlightSum(s, 'Release') },
  { name: 'charged-within-limit', pred: (s) => s.charged >= 0 && s.charged <= LIMIT },
  // A Refund in transit is still charged until the payment service receives it.
  { name: 'charged-is-held-amounts', pred: (s) => s.charged === CARTS.reduce((n, c) => n + chargedFor(s, c), 0) },
  // At rest the reserved units are those of the paid carts, plus those a declined
  // cart keeps while its customer decides; only paid carts are charged.
  {
    name: 'quiescent-settles',
    pred: (s) => s.net.length > 0 || (s.reserved === paidUnits(s) + unitsIn(s, 'declined') && s.charged === paidUnits(s)),
  },
  {
    name: 'quiescent-no-cart-waiting-on-a-message',
    pred: (s) => s.net.length > 0 || CARTS.every((c) => !['reserving', 'paying', 'cancelling', 'abandoning'].includes(status(s, c))),
  },
  { name: 'items-bounded', pred: (s) => CARTS.every((c) => items(s, c) >= 0 && items(s, c) <= 2) },
];

export const transitionInvariants = [
  {
    name: 'paid-only-after-reserved-and-charged',
    pred: (pre, action, data, post) => CARTS.every((c) => status(post, c) !== 'paid' || status(pre, c) === 'paid'
      || (status(pre, c) === 'paying' && delivered(action, data, `payments>${c}:Charged`))),
  },
  {
    name: 'paying-only-after-reserved-or-by-retry',
    pred: (pre, action, data, post) => CARTS.every((c) => status(post, c) !== 'paying' || status(pre, c) === 'paying'
      || (status(pre, c) === 'reserving' && delivered(action, data, `inventory>${c}:Reserved`))
      || (status(pre, c) === 'declined' && action === 'RETRY' && data.cart === c)),
  },
  {
    name: 'declined-only-by-declined-charge',
    pred: (pre, action, data, post) => CARTS.every((c) => status(post, c) !== 'declined' || status(pre, c) === 'declined'
      || (status(pre, c) === 'paying' && delivered(action, data, `payments>${c}:Declined`))),
  },
  {
    name: 'declined-leaves-only-by-retry-or-abandon',
    pred: (pre, action, data, post) => CARTS.every((c) => status(pre, c) !== 'declined' || status(post, c) === 'declined'
      || (status(post, c) === 'paying' && action === 'RETRY' && data.cart === c)
      || (status(post, c) === 'failed' && action === 'ABANDON' && data.cart === c)),
  },
  {
    name: 'abandon-gives-units-back',
    pred: (pre, action, data, post) => action !== 'ABANDON' || status(pre, data.cart) !== 'declined'
      || post.net.includes(`${data.cart}>inventory:Release:${items(pre, data.cart)}`),
  },
  {
    name: 'returned-only-from-paid-by-return',
    pred: (pre, action, data, post) => CARTS.every((c) => status(post, c) !== 'returned' || status(pre, c) === 'returned'
      || (status(pre, c) === 'paid' && action === 'RETURN' && data.cart === c)),
  },
  {
    name: 'paid-leaves-only-by-return',
    pred: (pre, _a, _d, post) => CARTS.every((c) => status(pre, c) !== 'paid' || ['paid', 'returned'].includes(status(post, c))),
  },
  {
    name: 'terminal-carts-stay-terminal',
    pred: (pre, _a, _d, post) => CARTS.every((c) => !TERMINAL.includes(status(pre, c))
      || (status(post, c) === status(pre, c) && items(post, c) === items(pre, c))),
  },
  {
    name: 'items-fixed-after-checkout',
    pred: (pre, _a, _d, post) => CARTS.every((c) => ['none', 'open'].includes(status(pre, c)) || items(post, c) === items(pre, c)),
  },
];

export const rejectionInvariants = [
  {
    name: 'cancel-refused-while-paying',
    pred: (pre, action, data, verdict) => !(action === 'CANCEL' && status(pre, data.cart) === 'paying') || verdict.rejected,
  },
  {
    name: 'return-refused-unless-paid',
    pred: (pre, action, data, verdict) => !(action === 'RETURN' && status(pre, data.cart) !== 'paid') || verdict.rejected,
  },
  {
    name: 'returned-cart-accepts-no-command',
    pred: (pre, action, data, verdict) => !(['ADD', 'CHECKOUT', 'CANCEL', 'RETURN', 'OPEN'].includes(action) && status(pre, data.cart) === 'returned') || verdict.rejected,
  },
  {
    name: 'declined-cart-accepts-only-retry-or-abandon',
    pred: (pre, action, data, verdict) => !(['ADD', 'CHECKOUT', 'CANCEL', 'RETURN', 'OPEN'].includes(action) && status(pre, data.cart) === 'declined') || verdict.rejected,
  },
  {
    name: 'retry-abandon-refused-unless-declined',
    pred: (pre, action, data, verdict) => !(['RETRY', 'ABANDON'].includes(action) && status(pre, data.cart) !== 'declined') || verdict.rejected,
  },
  {
    name: 'commands-on-unopened-cart-refused',
    pred: (pre, action, data, verdict) => !(['ADD', 'CHECKOUT', 'CANCEL', 'RETURN', 'RETRY', 'ABANDON'].includes(action) && status(pre, data.cart) === 'none') || verdict.rejected,
  },
];

export default { stateInvariants, transitionInvariants, rejectionInvariants };

