function project(s: State) {
  const out: Record<string, unknown> = {};
  for (const c of CARTS) {
    out[`${c}Status`] = s.carts[c] ? s.carts[c].status : 'none';
    out[`${c}Items`] = s.carts[c] ? s.carts[c].items : 0;
  }
  return { ...out, available: s.available, reserved: s.reserved, charged: s.charged, declining: s.declining, net: s.inFlight.map(msgName).sort() };
